[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ClipCast — One video is worth a thousand words</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{
  --blue:#1868DB;--blue-dark:#1255B8;--orange:#FF613D;--orange-dark:#E54F2E;
  --dark:#292A2E;--gray-900:#1a1a1f;--gray-800:#2d2e33;--gray-700:#44454a;
  --gray-600:#5e5f65;--gray-500:#7a7b82;--gray-400:#9d9ea5;--gray-300:#c2c3c8;
  --gray-200:#e2e3e6;--gray-100:#f3f4f6;--gray-50:#f9fafb;--white:#ffffff;
  --radius:12px;--radius-sm:8px;--radius-lg:16px;--radius-xl:24px;
  --shadow-sm:0 1px 2px rgba(0,0,0,.06);--shadow:0 2px 8px rgba(0,0,0,.08);
  --shadow-md:0 4px 16px rgba(0,0,0,.1);--shadow-lg:0 8px 32px rgba(0,0,0,.12);
  --transition:all .25s cubic-bezier(.4,0,.2,1);
}
html{scroll-behavior:smooth}
body{font-family:'Plus Jakarta Sans',sans-serif;color:var(--dark);background:var(--white);line-height:1.6;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
.container{max-width:1200px;margin:0 auto;padding:0 24px}

/* NAV */
.nav{position:fixed;top:0;left:0;right:0;z-index:1000;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--gray-200);transition:var(--transition)}
.nav-inner{display:flex;align-items:center;justify-content:space-between;height:64px;max-width:1200px;margin:0 auto;padding:0 24px}
.nav-logo{font-size:22px;font-weight:800;color:var(--dark);display:flex;align-items:center;gap:8px}
.nav-logo .logo-icon{width:32px;height:32px;background:var(--blue);border-radius:8px;display:flex;align-items:center;justify-content:center}
.nav-logo .logo-icon svg{width:18px;height:18px;fill:white}
.nav-links{display:flex;align-items:center;gap:32px}
.nav-links a{font-size:15px;font-weight:500;color:var(--gray-700);transition:var(--transition)}
.nav-links a:hover{color:var(--blue)}
.nav-actions{display:flex;align-items:center;gap:12px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 20px;border-radius:var(--radius-sm);font-family:inherit;font-size:15px;font-weight:600;cursor:pointer;border:none;transition:var(--transition);text-decoration:none}
.btn-primary{background:var(--blue);color:white}
.btn-primary:hover{background:var(--blue-dark);transform:translateY(-1px);box-shadow:var(--shadow-md)}
.btn-secondary{background:var(--gray-100);color:var(--dark)}
.btn-secondary:hover{background:var(--gray-200)}
.btn-outline{background:transparent;border:1.5px solid var(--gray-300);color:var(--dark)}
.btn-outline:hover{border-color:var(--blue);color:var(--blue)}
.btn-ghost{background:transparent;color:var(--gray-700)}
.btn-ghost:hover{color:var(--blue);background:var(--blue);background:rgba(24,104,219,.06)}
.btn-orange{background:var(--orange);color:white}
.btn-orange:hover{background:var(--orange-dark);transform:translateY(-1px);box-shadow:var(--shadow-md)}
.btn-lg{padding:14px 28px;font-size:16px;border-radius:var(--radius)}
.btn-sm{padding:8px 16px;font-size:14px}
.mobile-menu-btn{display:none;background:none;border:none;cursor:pointer;padding:8px}
.mobile-menu-btn span{display:block;width:24px;height:2px;background:var(--dark);margin:5px 0;transition:var(--transition)}

/* HERO */
.hero{padding:140px 0 80px;background:linear-gradient(170deg,#f0f5ff 0%,#ffffff 40%,#fff8f6 100%);position:relative;overflow:hidden}
.hero::before{content:'';position:absolute;top:-200px;right:-200px;width:600px;height:600px;background:radial-gradient(circle,rgba(24,104,219,.08) 0%,transparent 70%);pointer-events:none}
.hero::after{content:'';position:absolute;bottom:-100px;left:-100px;width:400px;height:400px;background:radial-gradient(circle,rgba(255,97,61,.06) 0%,transparent 70%);pointer-events:none}
.hero-inner{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;position:relative;z-index:1}
.hero-content{max-width:560px}
.hero h1{font-size:52px;font-weight:800;line-height:1.1;letter-spacing:-.02em;color:var(--dark);margin-bottom:20px}
.hero h1 span{background:linear-gradient(135deg,var(--blue),#6C5CE7);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.hero p{font-size:19px;color:var(--gray-600);line-height:1.65;margin-bottom:32px}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap}
.hero-visual{position:relative}
.hero-mockup{background:var(--white);border-radius:var(--radius-lg);box-shadow:var(--shadow-lg);border:1px solid var(--gray-200);padding:16px;position:relative}
.hero-mockup-screen{background:linear-gradient(135deg,#1a1a2e,#16213e);border-radius:var(--radius);aspect-ratio:16/10;display:flex;align-items:center;justify-content:center;position:relative;overflow:hidden}
.hero-mockup-screen::before{content:'';position:absolute;inset:0;background:linear-gradient(135deg,rgba(24,104,219,.15),rgba(108,92,231,.1));pointer-events:none}
.play-btn{width:72px;height:72px;background:rgba(255,255,255,.15);backdrop-filter:blur(8px);border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:var(--transition);border:2px solid rgba(255,255,255,.2);z-index:1}
.play-btn:hover{background:rgba(255,255,255,.25);transform:scale(1.08)}
.play-btn svg{fill:white;width:28px;height:28px;margin-left:4px}
.hero-badge{display:inline-flex;align-items:center;gap:6px;padding:6px 14px;background:rgba(24,104,219,.08);border:1px solid rgba(24,104,219,.15);border-radius:20px;font-size:13px;font-weight:600;color:var(--blue);margin-bottom:20px}
.hero-badge::before{content:'';width:6px;height:6px;background:var(--blue);border-radius:50%;animation:pulse-dot 2s infinite}
@keyframes pulse-dot{0%,100%{opacity:1}50%{opacity:.4}}
.floating-card{position:absolute;background:white;border-radius:var(--radius);box-shadow:var(--shadow-md);padding:12px 16px;display:flex;align-items:center;gap:10px;font-size:13px;font-weight:600;animation:float 6s ease-in-out infinite;border:1px solid var(--gray-100)}
.floating-card.card-1{top:-10px;right:-20px;animation-delay:0s}
.floating-card.card-2{bottom:20px;left:-30px;animation-delay:2s}
.floating-card .card-icon{width:36px;height:36px;border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.floating-card .card-icon svg{width:18px;height:18px}
@keyframes float{0%,100%{transform:translateY(0)}50%{transform:translateY(-10px)}}

/* SECTIONS */
.section{padding:80px 0}
.section-alt{background:var(--gray-50)}
.section-header{text-align:center;max-width:680px;margin:0 auto 56px}
.section-header h2{font-size:40px;font-weight:800;line-height:1.15;letter-spacing:-.015em;margin-bottom:16px;color:var(--dark)}
.section-header p{font-size:18px;color:var(--gray-600);line-height:1.6}
.section-label{display:inline-flex;align-items:center;gap:6px;padding:5px 12px;background:rgba(24,104,219,.08);border-radius:16px;font-size:13px;font-weight:600;color:var(--blue);margin-bottom:16px}

/* LOGO BAR */
.logo-bar{padding:48px 0;border-bottom:1px solid var(--gray-200)}
.logo-bar p{text-align:center;font-size:14px;color:var(--gray-500);margin-bottom:28px;font-weight:500}
.logo-grid{display:flex;align-items:center;justify-content:center;gap:48px;flex-wrap:wrap}
.logo-grid .brand{font-size:20px;font-weight:700;color:var(--gray-400);letter-spacing:-.01em;transition:var(--transition)}
.logo-grid .brand:hover{color:var(--gray-600)}

/* FEATURE HIGHLIGHT */
.feature-highlight{padding:80px 0;background:linear-gradient(180deg,var(--white),var(--gray-50))}
.feature-highlight-inner{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.feature-content .section-label{margin-bottom:16px}
.feature-content h2{font-size:36px;font-weight:800;line-height:1.15;margin-bottom:16px;color:var(--dark)}
.feature-content p{font-size:17px;color:var(--gray-600);line-height:1.65;margin-bottom:24px}
.feature-visual{background:linear-gradient(135deg,#f0f5ff,#e8eeff);border-radius:var(--radius-lg);padding:40px;display:flex;align-items:center;justify-content:center;aspect-ratio:4/3;position:relative;overflow:hidden}
.feature-visual::before{content:'';position:absolute;inset:0;background:url("data:image/svg+xml,%3Csvg width='40' height='40' xmlns='http://www.w3.org/2000/svg'%3E%3Cdefs%3E%3Cpattern id='g' width='40' height='40' patternUnits='userSpaceOnUse'%3E%3Ccircle cx='20' cy='20' r='1' fill='%231868DB' opacity='.08'/%3E%3C/pattern%3E%3C/defs%3E%3Crect fill='url(%23g)' width='40' height='40'/%3E%3C/svg%3E");pointer-events:none}
.feature-visual-card{background:white;border-radius:var(--radius);box-shadow:var(--shadow-md);padding:24px;width:80%;position:relative;z-index:1}
.feature-visual-card h4{font-size:14px;font-weight:700;margin-bottom:8px;color:var(--dark)}
.feature-visual-card .bar{height:8px;background:var(--gray-100);border-radius:4px;margin-bottom:6px;overflow:hidden}
.feature-visual-card .bar-fill{height:100%;background:linear-gradient(90deg,var(--blue),#6C5CE7);border-radius:4px}

/* SCREEN RECORDER */
.recorder-section{padding:80px 0}
.recorder-inner{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.recorder-visual{background:linear-gradient(135deg,#1a1a2e,#16213e);border-radius:var(--radius-lg);padding:32px;aspect-ratio:4/3;display:flex;align-items:center;justify-content:center;position:relative}
.recorder-ui{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:var(--radius);padding:20px;width:80%}
.recorder-ui .rec-dot{width:12px;height:12px;background:#ff4444;border-radius:50%;display:inline-block;margin-right:8px;animation:pulse-dot 1.5s infinite}
.recorder-ui span{color:rgba(255,255,255,.7);font-size:13px;font-weight:600}
.recorder-ui .toolbar{display:flex;gap:8px;margin-top:16px}
.recorder-ui .toolbar-item{width:36px;height:36px;background:rgba(255,255,255,.08);border-radius:8px;border:1px solid rgba(255,255,255,.1)}

/* VIDEO EDITOR */
.editor-section{padding:80px 0;background:var(--gray-50)}
.editor-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:32px;margin-top:48px}
.editor-card{background:white;border-radius:var(--radius-lg);padding:32px;border:1px solid var(--gray-200);transition:var(--transition)}
.editor-card:hover{border-color:var(--blue);box-shadow:var(--shadow-md);transform:translateY(-4px)}
.editor-card .card-icon-wrap{width:48px;height:48px;background:linear-gradient(135deg,rgba(24,104,219,.1),rgba(108,92,231,.1));border-radius:12px;display:flex;align-items:center;justify-content:center;margin-bottom:20px}
.editor-card .card-icon-wrap svg{width:24px;height:24px;color:var(--blue)}
.editor-card h3{font-size:19px;font-weight:700;margin-bottom:10px;color:var(--dark)}
.editor-card p{font-size:15px;color:var(--gray-600);line-height:1.6}

/* INTEGRATIONS */
.integrations-section{padding:80px 0}
.integrations-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:16px;max-width:700px;margin:0 auto}
.integration-tile{background:var(--white);border:1px solid var(--gray-200);border-radius:var(--radius);padding:20px;display:flex;align-items:center;justify-content:center;aspect-ratio:1;transition:var(--transition);font-weight:700;font-size:13px;color:var(--gray-600)}
.integration-tile:hover{border-color:var(--blue);box-shadow:var(--shadow);transform:translateY(-2px)}

/* SECURITY */
.security-section{padding:80px 0;background:linear-gradient(180deg,var(--gray-50),var(--white))}
.security-inner{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.security-list{list-style:none;padding:0}
.security-list li{display:flex;align-items:flex-start;gap:14px;padding:14px 0;font-size:16px;color:var(--gray-700);line-height:1.5}
.security-list li svg{width:22px;height:22px;color:var(--blue);flex-shrink:0;margin-top:2px}
.security-visual{background:linear-gradient(135deg,#f0f5ff,#e8eeff);border-radius:var(--radius-lg);padding:48px;display:flex;align-items:center;justify-content:center;aspect-ratio:1}
.shield-icon{width:120px;height:120px;background:linear-gradient(135deg,var(--blue),#6C5CE7);border-radius:24px;display:flex;align-items:center;justify-content:center;box-shadow:0 20px 60px rgba(24,104,219,.25)}
.shield-icon svg{width:56px;height:56px;fill:white}

/* USE CASES */
.use-cases-section{padding:80px 0}
.use-cases-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.use-case-card{background:white;border:1px solid var(--gray-200);border-radius:var(--radius-lg);padding:32px 24px;text-align:center;transition:var(--transition);cursor:pointer}
.use-case-card:hover{border-color:var(--blue);box-shadow:var(--shadow-md);transform:translateY(-4px)}
.use-case-card .uc-icon{width:56px;height:56px;border-radius:14px;display:flex;align-items:center;justify-content:center;margin:0 auto 18px}
.use-case-card .uc-icon svg{width:26px;height:26px}
.uc-sales .uc-icon{background:rgba(255,97,61,.1)}
.uc-sales .uc-icon svg{color:var(--orange)}
.uc-eng .uc-icon{background:rgba(24,104,219,.1)}
.uc-eng .uc-icon svg{color:var(--blue)}
.uc-support .uc-icon{background:rgba(16,185,129,.1)}
.uc-support .uc-icon svg{color:#10b981}
.uc-design .uc-icon{background:rgba(168,85,247,.1)}
.uc-design .uc-icon svg{color:#a855f7}
.use-case-card h3{font-size:18px;font-weight:700;margin-bottom:8px;color:var(--dark)}
.use-case-card p{font-size:14px;color:var(--gray-600);line-height:1.55}

/* FEATURES GRID */
.features-grid-section{padding:80px 0;background:var(--gray-50)}
.features-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.feature-tile{background:white;border:1px solid var(--gray-200);border-radius:var(--radius);padding:24px;transition:var(--transition)}
.feature-tile:hover{border-color:var(--blue);box-shadow:var(--shadow)}
.feature-tile .ft-icon{width:40px;height:40px;background:rgba(24,104,219,.08);border-radius:10px;display:flex;align-items:center;justify-content:center;margin-bottom:14px}
.feature-tile .ft-icon svg{width:20px;height:20px;color:var(--blue)}
.feature-tile h4{font-size:15px;font-weight:700;color:var(--dark);margin-bottom:4px}

/* BLOG */
.blog-section{padding:80px 0}
.blog-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px}
.blog-card{background:white;border:1px solid var(--gray-200);border-radius:var(--radius-lg);overflow:hidden;transition:var(--transition)}
.blog-card:hover{box-shadow:var(--shadow-md);transform:translateY(-4px)}
.blog-card-img{background:linear-gradient(135deg,#e8eeff,#f0f5ff);height:200px;display:flex;align-items:center;justify-content:center;font-size:48px}
.blog-card-body{padding:28px}
.blog-card-body h3{font-size:19px;font-weight:700;margin-bottom:10px;color:var(--dark);line-height:1.35}
.blog-card-body p{font-size:14px;color:var(--gray-600);line-height:1.6}
.blog-card-body .read-more{display:inline-flex;align-items:center;gap:6px;color:var(--blue);font-weight:600;font-size:14px;margin-top:14px}

/* ENTERPRISE CTA */
.enterprise-cta{padding:80px 0;background:linear-gradient(135deg,#1a1a2e,#16213e);color:white;text-align:center}
.enterprise-cta h2{font-size:36px;font-weight:800;margin-bottom:12px}
.enterprise-cta p{font-size:18px;opacity:.75;margin-bottom:28px}
.enterprise-cta .btn-primary{background:white;color:var(--blue)}
.enterprise-cta .btn-primary:hover{background:var(--gray-100);color:var(--blue-dark)}

/* TESTIMONIALS */
.testimonials-section{padding:80px 0;background:var(--gray-50)}
.testimonials-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.testimonial-card{background:white;border:1px solid var(--gray-200);border-radius:var(--radius-lg);padding:32px;transition:var(--transition)}
.testimonial-card:hover{box-shadow:var(--shadow)}
.testimonial-card .quote{font-size:15px;color:var(--gray-700);line-height:1.65;margin-bottom:20px;font-style:italic}
.testimonial-card .author{display:flex;align-items:center;gap:12px}
.testimonial-card .avatar{width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,var(--blue),#6C5CE7);display:flex;align-items:center;justify-content:center;color:white;font-weight:700;font-size:16px}
.testimonial-card .author-info .name{font-size:14px;font-weight:700;color:var(--dark)}
.testimonial-card .author-info .role{font-size:13px;color:var(--gray-500)}

/* CTA BANNER */
.cta-banner{padding:80px 0;text-align:center}
.cta-banner-inner{background:linear-gradient(135deg,var(--blue),#6C5CE7);border-radius:var(--radius-xl);padding:64px 48px;color:white;position:relative;overflow:hidden}
.cta-banner-inner::before{content:'';position:absolute;top:-50%;right:-20%;width:60%;height:200%;background:radial-gradient(circle,rgba(255,255,255,.08) 0%,transparent 60%);pointer-events:none}
.cta-banner h2{font-size:36px;font-weight:800;margin-bottom:12px;position:relative;z-index:1}
.cta-banner p{font-size:16px;opacity:.8;margin-bottom:28px;position:relative;z-index:1}
.cta-banner .btn{position:relative;z-index:1;background:white;color:var(--blue);font-weight:700}
.cta-banner .btn:hover{background:var(--gray-100);transform:translateY(-2px);box-shadow:var(--shadow-lg)}

/* FOOTER */
.footer{background:var(--gray-900);color:var(--gray-400);padding:64px 0 32px}
.footer-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:32px;margin-bottom:48px}
.footer-col h4{color:var(--white);font-size:14px;font-weight:700;margin-bottom:16px;text-transform:uppercase;letter-spacing:.05em}
.footer-col a{display:block;font-size:13px;color:var(--gray-400);padding:4px 0;transition:var(--transition)}
.footer-col a:hover{color:white}
.footer-bottom{border-top:1px solid var(--gray-800);padding-top:24px;display:flex;justify-content:space-between;align-items:center;font-size:13px}
.footer-bottom a{color:var(--gray-500);margin-left:20px}
.footer-bottom a:hover{color:white}

/* COOKIE BANNER */
.cookie-banner{position:fixed;bottom:0;left:0;right:0;background:white;border-top:1px solid var(--gray-200);box-shadow:0 -4px 24px rgba(0,0,0,.1);z-index:9999;padding:20px 0;transform:translateY(0);transition:transform .4s ease}
.cookie-banner.hidden{transform:translateY(100%);pointer-events:none}
.cookie-inner{display:flex;align-items:center;justify-content:space-between;gap:24px;max-width:1200px;margin:0 auto;padding:0 24px}
.cookie-text{font-size:14px;color:var(--gray-700);flex:1}
.cookie-text a{color:var(--blue);font-weight:600}
.cookie-actions{display:flex;gap:10px;flex-shrink:0}

/* COOKIE MODAL */
.cookie-overlay{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:10000;display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;transition:opacity .3s}
.cookie-overlay.active{opacity:1;pointer-events:auto}
.cookie-modal{background:white;border-radius:var(--radius-lg);max-width:520px;width:90%;max-height:80vh;overflow-y:auto;padding:32px}
.cookie-modal h3{font-size:20px;font-weight:700;margin-bottom:8px;color:var(--dark)}
.cookie-modal>p{font-size:14px;color:var(--gray-600);margin-bottom:24px}
.cookie-category{display:flex;align-items:center;justify-content:space-between;padding:16px 0;border-top:1px solid var(--gray-200)}
.cookie-category-info h4{font-size:15px;font-weight:600;color:var(--dark);margin-bottom:2px}
.cookie-category-info p{font-size:13px;color:var(--gray-500)}
.toggle-switch{position:relative;width:44px;height:24px;flex-shrink:0}
.toggle-switch input{opacity:0;width:0;height:0}
.toggle-slider{position:absolute;cursor:pointer;inset:0;background:var(--gray-300);border-radius:12px;transition:var(--transition)}
.toggle-slider::before{content:'';position:absolute;height:18px;width:18px;left:3px;bottom:3px;background:white;border-radius:50%;transition:var(--transition)}
.toggle-switch input:checked+.toggle-slider{background:var(--blue)}
.toggle-switch input:checked+.toggle-slider::before{transform:translateX(20px)}
.toggle-switch input:disabled+.toggle-slider{opacity:.5;cursor:default}
.cookie-modal-actions{display:flex;gap:10px;margin-top:24px;justify-content:flex-end}

/* ANIMATIONS */
.fade-up{opacity:0;transform:translateY(24px);transition:opacity .6s ease,transform .6s ease}
.fade-up.visible{opacity:1;transform:translateY(0)}
.stagger-1{transition-delay:.1s}
.stagger-2{transition-delay:.2s}
.stagger-3{transition-delay:.3s}
.stagger-4{transition-delay:.4s}

/* RESPONSIVE */
@media(max-width:1024px){
  .hero-inner{grid-template-columns:1fr;gap:40px;text-align:center}
  .hero-content{max-width:100%}
  .hero-actions{justify-content:center}
  .hero h1{font-size:40px}
