.team-slider-label{font-size:14px;color:var(--gray-600);margin-bottom:12px;font-weight:500}
.team-slider-label strong{color:var(--dark);font-size:16px}
.team-slider{width:300px;max-width:100%;-webkit-appearance:none;appearance:none;height:6px;border-radius:3px;background:var(--gray-200);outline:none;cursor:pointer}
