.team-slider::-moz-range-thumb{width:22px;height:22px;border-radius:50%;background:var(--blue);cursor:pointer;border:none}
.team-rec{margin-top:10px;font-size:13px;color:var(--blue);font-weight:600;min-height:20px}

/* PRICING CARDS */
