.pricing-card.popular::before{content:'MOST POPULAR';position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:var(--blue);color:white;font-size:11px;font-weight:700;padding:4px 12px;border-radius:12px;white-space:nowrap}
.pricing-card h3{font-size:20px;font-weight:700;margin-bottom:8px;color:var(--dark)}
.pricing-card .price{font-size:40px;font-weight:800;color:var(--dark);margin-bottom:4px;line-height:1.1}
.pricing-card .price .currency{font-size:20px;vertical-align:top;line-height:1.8}
.pricing-card .price .period{font-size:15px;font-weight:500;color:var(--gray-500)}
.pricing-card .price-note{font-size:13px;color:var(--gray-500);margin-bottom:20px;min-height:18px}
.pricing-card .plan-features{list-style:none;padding:0;margin-bottom:24px;flex:1}
.pricing-card .plan-features li{font-size:14px;color:var(--gray-700);padding:6px 0;display:flex;align-items:flex-start;gap:8px}
.pricing-card .plan-features li svg{width:16px;height:16px;color:var(--blue);flex-shrink:0;margin-top:2px}
.pricing-card .btn{width:100%;margin-top:auto}
.see-features-btn{display:block;text-align:center;color:var(--blue);font-size:13px;font-weight:600;cursor:pointer;margin-top:12px;background:none;border:none;font-family:inherit;padding:4px}
