.ai-section{padding:80px 0;background:linear-gradient(135deg,#f0f5ff,#f8f0ff)}
.ai-inner{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.ai-features-list{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.ai-feature-item{display:flex;align-items:center;gap:10px;padding:12px 16px;background:white;border-radius:var(--radius);border:1px solid var(--gray-200);font-size:14px;font-weight:600;color:var(--dark)}
