.comparison-table thead th{padding:16px 12px;font-weight:700;font-size:15px;color:var(--dark);text-align:center;border-bottom:2px solid var(--gray-200);position:sticky;top:0;background:white}
.comparison-table thead th:first-child{text-align:left}
.comparison-table thead th.popular-col{color:var(--blue)}
.comparison-table tbody tr{border-bottom:1px solid var(--gray-100)}
.comparison-table tbody tr:hover{background:var(--gray-50)}
.comparison-table tbody td{padding:14px 12px;text-align:center;color:var(--gray-700)}
.comparison-table tbody td:first-child{text-align:left;font-weight:500;color:var(--dark)}
