.table-toggle button svg{transition:var(--transition)}
.table-toggle button.expanded svg{transform:rotate(180deg)}
.comparison-table.collapsed tbody tr.extra-row{display:none}

/* FAQ */
.faq-section{padding:80px 0;background:var(--gray-50)}
