.faq-answer{max-height:0;overflow:hidden;transition:max-height .35s ease,padding .35s ease}
.faq-item.open .faq-answer{max-height:400px}
.faq-answer-inner{padding:0 24px 20px;font-size:15px;color:var(--gray-600);line-height:1.65}

/* LOGO BAR */
.logo-bar{padding:48px 0;border-bottom:1px solid var(--gray-200)}
.logo-bar p{text-align:center;font-size:14px;color:var(--gray-500);margin-bottom:28px;font-weight:500}
.logo-grid{display:flex;align-items:center;justify-content:center;gap:48px;flex-wrap:wrap}
.logo-grid .brand{font-size:20px;font-weight:700;color:var(--gray-400)}

/* CTA BANNER */
.cta-banner{padding:80px 0;text-align:center}
