.cta-banner-inner::before{content:'';position:absolute;top:-50%;right:-20%;width:60%;height:200%;background:radial-gradient(circle,rgba(255,255,255,.08) 0%,transparent 60%);pointer-events:none}
.cta-banner h2{font-size:36px;font-weight:800;margin-bottom:12px;position:relative;z-index:1}
.cta-banner p{font-size:16px;opacity:.8;margin-bottom:28px;position:relative;z-index:1}
.cta-banner .btn{position:relative;z-index:1;background:white;color:var(--blue);font-weight:700}
.cta-banner .btn:hover{background:var(--gray-100);transform:translateY(-2px);box-shadow:var(--shadow-lg)}

/* FOOTER */
.footer{background:var(--gray-900);color:var(--gray-400);padding:64px 0 32px}
.footer-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:32px;margin-bottom:48px}
.footer-col h4{color:var(--white);font-size:14px;font-weight:700;margin-bottom:16px;text-transform:uppercase;letter-spacing:.05em}
.footer-col a{display:block;font-size:13px;color:var(--gray-400);padding:4px 0;transition:var(--transition)}
.footer-col a:hover{color:white}
.footer-bottom{border-top:1px solid var(--gray-800);padding-top:24px;display:flex;justify-content:space-between;align-items:center;font-size:13px}
.footer-bottom a{color:var(--gray-500);margin-left:20px}
.footer-bottom a:hover{color:white}

/* ANIMATIONS */
.fade-up{opacity:0;transform:translateY(24px);transition:opacity .6s ease,transform .6s ease}
.fade-up.visible{opacity:1;transform:translateY(0)}
.stagger-1{transition-delay:.1s}
.stagger-2{transition-delay:.2s}
.stagger-3{transition-delay:.3s}
.stagger-4{transition-delay:.4s}

@media(max-width:1024px){
