<script>
// Scroll animations
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) entry.target.classList.add('visible');
  });
}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });
document.querySelectorAll('.fade-up').forEach(el => observer.observe(el));

// Billing toggle
const billingToggle = document.getElementById('billingToggle');
const labelMonthly = document.getElementById('labelMonthly');
const labelAnnually = document.getElementById('labelAnnually');
const priceBusiness = document.getElementById('priceBusiness');
const priceBusinessAI = document.getElementById('priceBusinessAI');
const notesBusiness = document.getElementById('notesBusiness');
const notesBusinessAI = document.getElementById('notesBusinessAI');

const prices = {
  monthly: { business: 18, businessAI: 24 },
  annual: { business: 15, businessAI: 20 }
};

billingToggle.addEventListener('change', function() {
  const isAnnual = this.checked;
  labelMonthly.classList.toggle('active', !isAnnual);
  labelAnnually.classList.toggle('active', isAnnual);

  if (isAnnual) {
    priceBusiness.innerHTML = '<span class="currency">$</span>' + prices.annual.business + '<span class="period">/user/mo</span>';
    priceBusinessAI.innerHTML = '<span class="currency">$</span>' + prices.annual.businessAI + '<span class="period">/user/mo</span>';
    notesBusiness.textContent = 'Billed annually';
    notesBusinessAI.textContent = 'Billed annually';
  } else {
    priceBusiness.innerHTML = '<span class="currency">$</span>' + prices.monthly.business + '<span class="period">/user/mo</span>';
    priceBusinessAI.innerHTML = '<span class="currency">$</span>' + prices.monthly.businessAI + '<span class="period">/user/mo</span>';
    notesBusiness.textContent = 'Billed monthly';
    notesBusinessAI.textContent = 'Billed monthly';
  }
});

// Team size slider
const teamSlider = document.getElementById('teamSlider');
const teamSizeValue = document.getElementById('teamSizeValue');
const teamRec = document.getElementById('teamRec');

teamSlider.addEventListener('input', function() {
  const size = parseInt(this.value);
  teamSizeValue.textContent = size + (size === 1 ? ' member' : ' members');

  if (size <= 5) {
    teamRec.textContent = 'Starter plan is great for small teams';
  } else if (size <= 25) {
    teamRec.textContent = 'Business plan recommended for teams of ' + size;
  } else if (size <= 100) {
    teamRec.textContent = 'Business + AI plan recommended for teams of ' + size;
  } else {
    teamRec.textContent = 'Enterprise plan recommended for organizations of ' + size + '+';
  }
});

// Comparison table toggle
const table = document.getElementById('comparisonTable');
table.classList.add('collapsed');
function toggleTable() {
  const btn = document.getElementById('tableToggleBtn');
  table.classList.toggle('collapsed');
  const isCollapsed = table.classList.contains('collapsed');
  btn.innerHTML = (isCollapsed ? 'See all features' : 'Show less') + ' <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>';
  btn.classList.toggle('expanded', !isCollapsed);
}

// FAQ accordion
function toggleFaq(btn) {
  const item = btn.closest('.faq-item');
  const wasOpen = item.classList.contains('open');
  document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
  if (!wasOpen) item.classList.add('open');
}
</script>
