.social-btn:hover{border-color:var(--gray-400);background:var(--gray-50);transform:translateY(-1px)}
.social-btn svg{width:20px;height:20px;flex-shrink:0}

.divider{display:flex;align-items:center;gap:16px;margin:24px 0;color:var(--gray-400);font-size:13px;font-weight:500}
.divider::before,.divider::after{content:'';flex:1;height:1px;background:var(--gray-200)}

.form-group{margin-bottom:16px}
.form-group label{display:block;font-size:14px;font-weight:600;color:var(--dark);margin-bottom:6px}
.form-group input{width:100%;padding:12px 16px;border:1.5px solid var(--gray-200);border-radius:var(--radius-sm);font-family:inherit;font-size:15px;color:var(--dark);transition:var(--transition);outline:none;background:white}
.form-group input:focus{border-color:var(--blue);box-shadow:0 0 0 3px rgba(24,104,219,.1)}
.form-group input::placeholder{color:var(--gray-400)}

.submit-btn{width:100%;padding:14px;border:none;border-radius:var(--radius-sm);background:var(--blue);color:white;font-family:inherit;font-size:16px;font-weight:700;cursor:pointer;transition:var(--transition);margin-top:8px}
.submit-btn:hover{background:var(--blue-dark);transform:translateY(-1px);box-shadow:var(--shadow-md)}

.form-footer{margin-top:20px;font-size:13px;color:var(--gray-500);line-height:1.5}
.form-footer a{color:var(--blue);font-weight:600}
.form-footer a:hover{text-decoration:underline}

.login-link{margin-top:20px;font-size:14px;color:var(--gray-600)}
.login-link a{color:var(--blue);font-weight:600}
.login-link a:hover{text-decoration:underline}

/* RIGHT: TESTIMONIAL */
.testimonial-side{background:linear-gradient(160deg,#0d1b3e,#1a3570,#1868DB);color:white;display:flex;align-items:center;justify-content:center;padding:64px;position:relative;overflow:hidden}
.testimonial-side::before{content:'';position:absolute;top:-200px;right:-200px;width:500px;height:500px;background:radial-gradient(circle,rgba(255,255,255,.06) 0%,transparent 70%);pointer-events:none}
.testimonial-side::after{content:'';position:absolute;bottom:-100px;left:-100px;width:400px;height:400px;background:radial-gradient(circle,rgba(108,92,231,.2) 0%,transparent 70%);pointer-events:none}
.testimonial-content{max-width:440px;position:relative;z-index:1}
.testimonial-content .big-quote{font-size:14px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;opacity:.5;margin-bottom:24px}
.testimonial-content blockquote{font-size:22px;font-weight:500;line-height:1.5;margin-bottom:32px;font-style:italic;opacity:.95}
.testimonial-content .author{display:flex;align-items:center;gap:14px}
.testimonial-content .avatar{width:48px;height:48px;border-radius:50%;background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-weight:700;font-size:20px}
.testimonial-content .author-name{font-size:15px;font-weight:700}
.testimonial-content .author-role{font-size:14px;opacity:.65}

.stars{display:flex;gap:4px;margin-bottom:16px}
.stars svg{width:18px;height:18px;fill:#fbbf24}

@media(max-width:1024px){
  .signup-layout{grid-template-columns:1fr}
  .testimonial-side{display:none}
}
@media(max-width:480px){
  .signup-form-side{padding:24px}
  .signup-form-inner h1{font-size:24px}
}
</style>
